    const int batch_index = static_cast<int>(blockIdx.z);
    const int source_row_base = tile_row * 32;
    const int source_col = tile_col * 32 + threadIdx.x;
    for (int offset = 0; offset < 32; offset += 8) {
        const int source_row = source_row_base + threadIdx.y + offset;
